-- GENERATED by `wfi generate` from data/quest/quest-0000.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [6] = { "Una taglia su Garrick Padfoot", "Uccidi Garrick Padfoot e porta la sua testa a Deputy Willem, alla Northshire Abbey.", "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato visto in una baracca vicino ai vigneti, a est dell'abbazia, oltre il ponte. Portami la testa di quel furfante e guadagnati la taglia!\n\nMa stai in guardia, {name}. Garrick ha radunato intorno a sé una banda di delinquenti. Non sarà facile arrivare fino a lui.", "Hai trovato la baracca di Garrick? Siamo finalmente liberi da quel furfante?", "Ah! L'hai preso! Hai reso un grande servizio a Elwynn, e ora una bella taglia è tutta tua!", 0xd9a1ea2f, 0xb35875a3, 0x674275ec, 0xe205dce0, 0x8edda1cf, "....." },
  [7] = { "Ripulire il campo dei kobold", "Uccidi 10 Kobold Vermin, poi torna da Marshal McBride.", "Il tuo primo compito sarà fare pulizia, {name}. Un clan di kobold ha infestato i boschi a nord. Vai là e combatti i Kobold Vermin che trovi. Riducine il numero, così che un giorno potremo cacciarli da Northshire.", "Come va la caccia, {name}? Hai trovato e sconfitto quei parassiti?", "Ben fatto, <cittadino/cittadina>. Quei kobold sono ladri e codardi, ma in gran numero sono una minaccia per noi. E agli umani di Stormwind non serve un'altra minaccia.\n\nPer averli sconfitti, hai la mia gratitudine.", 0x5d10a531, 0xc0a62578, 0x54635c79, 0x4eb51373, 0xb52dae46, "....." },
  [11] = { "Taglia sugli gnoll Riverpaw", "Porta 8 Painted Gnoll Armbands a Deputy Rainer, alle Barracks.", "Gli gnoll, creature brutali che non hanno nulla da fare in queste terre, sono stati avvistati lungo i confini della Elwynn Forest. Un grosso branco, molto più numeroso di quanto possiamo affrontare da soli, ha infestato i boschi a sud della torre di guardia laggiù. Un altro gruppo ha infestato le zone vicino allo Stone Cairn Lake, a est.\n\nLa Stormwind Army ricompenserà chiunque aiuti a ucciderli. Portami i loro Painted Gnoll Armbands come prova dell'impresa.", "Salute, {name}. Hai ucciso degli gnoll...?", "Vedo che ti sei <dato/data> da fare! Hai la nostra gratitudine, {name}.", 0x9b53bb87, 0x8f6713f0, 0x9259d68e, 0x11769f64, 0xc6ac4114, "....." },
  [15] = { "Indagini a Echo Ridge", "Uccidi 10 Kobold Workers, poi torna a fare rapporto a Marshal McBride.", "{name}, i miei esploratori dicono che l'infestazione di kobold è più estesa di quanto pensassimo. Un gruppo di Kobold Workers si è accampato vicino alla Echo Ridge Mine, a nord.\n\nVai alla miniera e toglili di mezzo. Sappiamo che sono almeno 10. Uccidili, controlla se ce ne sono altri, poi torna a farmi rapporto.", "Sei <andato/andata> alle miniere? Sei <pronto/pronta> a fare rapporto?", "Non mi piace sentire di tutti questi kobold nella nostra miniera. Non ne verrà niente di buono. Ecco, prendi questo come compenso, e quando sei <pronto/pronta> parlami di nuovo. Vorrei che tornassi alle miniere ancora una volta...", 0xb43a6289, 0xa368f704, 0x2cb816b5, 0x063df25d, 0xf0b6a1c7, "....." },
  [16] = { "Da bere per Gerard", nil, nil, "Lavorare nei campi mette sete, e cerco sempre acqua fresca di sorgente.\n\nSe ne hai un po', sono disposto a fare uno scambio.", "Grazie, {name}! E torna se vuoi fare un altro scambio.", 0x8a697a25, nil, nil, 0x6a289e06, 0x46e9e47e, ".mm.." },
  [18] = { "La confraternita dei ladri", "Porta 12 Red Burlap Bandanas a Deputy Willem, fuori dalla Northshire Abbey.", "Da poco un nuovo gruppo di ladri si aggira intorno a Northshire. Si fanno chiamare Defias Brotherhood e sono stati visti oltre il fiume, a est.\n\nNon so cosa stiano tramando, ma di sicuro niente di buono! Portami le bandane che indossano e ti ricompenserò con un'arma.", "Hai già raccolto quelle bandane per me?", "Vedo che hai portato qualche bandana. La Stormwind Army ti è grata per il tuo aiuto.", 0x2f1eb64e, 0x0376329b, 0x0ff5818f, 0x59c5a6d0, 0x9eec7aad, "....." },
  [21] = { "Scaramuccia a Echo Ridge", "Uccidi 12 Kobold Laborers, poi torna da Marshal McBride alla Northshire Abbey.", "Le tue indagini hanno dimostrato che la Echo Ridge Mine va ripulita. Torna alla miniera e aiuta a liberarla dai kobold.\n\nNon perdere tempo, {name}. Più a lungo i kobold restano indisturbati nella miniera, più saldamente mettono radici a Northshire.", "So che è un lavoro sanguinoso, {name}, ma è vitale per la sicurezza di Northshire. Sei <pronto/pronta> a fare rapporto?", "Ancora una volta hai conquistato il mio rispetto e la gratitudine della Stormwind Army. Forse nella miniera ci sono ancora dei kobold, ma radunerò altri soldati contro di loro. Abbiamo altri compiti per te.", 0xa7a12dbe, 0x26b99d1f, 0xeb16bc2b, 0xf565255c, 0x019e5401, "....." },
  [33] = { "Lupi oltre il confine", "Porta 8 pezzi di Tough Wolf Meat a Eagan Peltskinner, fuori dalla Northshire Abbey.", "Odio quei maledetti lupi dei boschi! Però le bistecche di lupo mi piacciono proprio... Portami della Tough Wolf Meat e te la scambierò con qualcosa che ti tornerà utile.\n\nLa Tough Wolf Meat si ricava cacciando i lupi dei boschi e i lupi giovani che vagano per le campagne di Northshire.", "Ehi, {name}. Comincio ad avere fame... hai preso quella Tough Wolf Meat?", "Hai lavorato sodo! Non vedo l'ora di cucinare quella carne di lupo...\n\nHo qui alcune cose che potrebbero interessarti: scegli pure!", 0xf2272f07, 0xdf199ead, 0x5ce8cfac, 0xf5cb8e2e, 0x63c80a97, "....." },
  [35] = { "Altre preoccupazioni", "Marshal Dughan vuole che tu parli con Guard Thomas.", "Se temi che le voci sui murloc siano vere, allora fai così: vai al ponte orientale di Elwynn e parla con Guard Thomas. È di stanza al ponte da una settimana e saprà com'è la situazione nella zona.\n\nPortami il suo rapporto.", nil, "Sì, i murloc si sono stabiliti lungo i torrenti della parte orientale di Elwynn e nei dintorni. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.", 0xbf37aefc, 0xd1c199f2, 0x0d41f7ae, nil, 0xfbe5b854, "...m." },
  [37] = { "Trovare le guardie scomparse", "Guard Thomas vuole che tu risalga il fiume verso nord e cerchi le due guardie scomparse, Rolf e Malakai.", "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a indagare lungo il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere che fine hanno fatto.\n\nRisali il fiume verso nord e trova le guardie... o quello che ne resta.", nil, "Anche se il cadavere è stato in gran parte spogliato, lì vicino c'è un medaglione con incise le parole: \"Footman Malakai Stone\".", 0xbd0b84c3, 0xc79cfdb3, 0x96ec21d0, nil, 0xf410e026, "...m." },
  [39] = { "Consegnare il rapporto di Thomas", "Fai rapporto a Marshal Dughan, a Goldshire.", "Riferisci a Marshal Dughan della morte di Malakai e Rolf, e digli che con le truppe che abbiamo ora non possiamo contenere i murloc nella parte orientale di Elwynn.\n\nSo che non abbiamo molti uomini da mandare, ma speriamo che Dughan trovi qualcuno.", nil, "Mmm, queste notizie sono preoccupanti. Le nostre difese sono già allo stremo, e perdere Rolf e Malakai per colpa di quei murloc ci mette in una posizione ancora peggiore.\n\nSe le cose non migliorano, entro la fine della settimana si combatterà a Goldshire!", 0x25228270, 0x3f1aa863, 0x2d7986ad, nil, 0xae2657cb, "...m." },
  [40] = { "Un pericolo che sa di pesce", "Remy \"Two Times\" vuole che tu parli con Marshal Dughan, a Goldshire.", "{name}, c'è una nuova minaccia nella Elwynn Forest! I murloc risalgono i torrenti della parte orientale di Elwynn, fanno scappare i pesci e aggrediscono la brava gente!\n\nHo avvertito Marshal Dughan, ma lui si preoccupa di più degli gnoll e dei banditi. Non è convinto che i murloc siano un pericolo.\n\nTi prego, {name}, parla con Dughan e convincilo a mandare altre truppe a est!", nil, "Sì, ho parlato con Remy. Lo rispetto come mercante, ma le voci sui murloc a est sono state a dir poco vaghe.\n\nPrendo nota delle tue preoccupazioni, ma a meno che non riceva un rapporto militare su una minaccia dei murloc, non possiamo permetterci di mandare altre truppe a est.", 0x02cfe285, 0x67e1f5a8, 0xb8d781bd, nil, 0xf6272f28, "...m." },
  [45] = { "Scoprire la sorte di Rolf", "Cerca Rolf nel villaggio dei murloc, o segni della sua morte.", "Cercando ancora nella zona, trovi impronte palmate che vanno verso est lungo la riva dello Stone Cairn Lake. In lontananza, a est, riesci a malapena a scorgere un villaggio di murloc.\n\nForse è lì che Rolf ha trovato la sua fine...", nil, "Al collo del cadavere trovi un medaglione di metallo con incise le parole \"Footman Rolf Hartford.\"", 0x119e499d, 0x93412d0c, 0xbf0a2396, nil, 0x0692a2fa, "...m." },
  [46] = { "Taglia sui murloc", "Porta 8 Torn Murloc Fins a Guard Thomas, al ponte orientale di Elwynn.", "La Stormwind Army ha messo una taglia sui murloc lurker e forager di Elwynn. Fanne strage e portami le loro Torn Murloc Fins: la Stormwind Army ti ricompenserà bene.\n\nI murloc hanno costruito un villaggio allo Stone Cairn Lake, a nord di qui, e un altro a sud, dove il torrente si divide.", "Come va la caccia, {name}?", "Hai le pinne? Ottimo! Marshal Dughan è in ansia per la situazione dei murloc nella parte orientale di Elwynn, e mi piacerebbe dirgli che la stiamo mettendo sotto controllo.\n\nLe tue azioni hanno contribuito a renderlo possibile.", 0xd7ee6932, 0x320c64a3, 0x05a40606, 0xd84cca78, 0xff08c2c6, "....." },
  [47] = { "Scambio di Gold Dust", "Porta 10 Gold Dust a Remy \"Two Times\", a Goldshire. La Gold Dust si raccoglie dai kobold della Elwynn Forest.", "I kobold da queste parti a volte si portano dietro della Gold Dust. Mi farebbe proprio comodo: portamene un bel po' e ti farò il miglior prezzo in città... il miglior prezzo in città!\n\nTrovi i kobold nella Fargodeep Mine, a sud, e intorno alla Jasperlode Mine, a nord-est.", "Psst! Hai quella Gold Dust per me... per me?", "Grazie per la polvere, {name}. Ecco i tuoi soldi, e... ecco un pegno da parte di alcuni miei soci. Potrebbe tornarti utile... utile.", 0x6fc1c811, 0x54bcff94, 0xcbdc7c22, 0xfc397987, 0x26e50fd4, "....." },
  [52] = { "Proteggere la frontiera", "Uccidi 8 Prowlers e 5 Young Forest Bears, poi torna da Guard Thomas al ponte orientale di Elwynn.", "Salute, {name}. Più ci si allontana da Goldshire, più gli animali selvatici diventano aggressivi, e l'Eastvale Logging Camp subisce attacchi quasi continui da lupi e orsi!\n\nCi farebbe comodo il tuo aiuto qui.", "Hai ucciso quei lupi e quegli orsi?", "Grazie mille per l'aiuto, {name}. Qualcosa nella foresta deve rendere questi animali così audaci.\n\nQualunque cosa sia, spero che resti lì.", 0x2e116184, 0x03f5e0ac, 0x866a4bcd, 0xfcb3bc90, 0xe7a250d3, "....." },
  [54] = { "Rapporto a Goldshire", "Porta i Marshal McBride's Documents a Marshal Dughan, a Goldshire.", "{name}, come {class} hai dimostrato di avere a cuore la sicurezza di Northshire. Ora ti viene affidata la protezione della Elwynn Forest che la circonda.\n\nSe accetti questo incarico, ho preparato dei documenti da consegnare a Marshal Dughan, a Goldshire. Goldshire si trova lungo la strada a sud, oltre i cancelli di confine.", "Hai notizie da McBride? Northshire è un giardino in confronto alla Elwynn Forest, ma chissà cosa ha da riferire Marshal McBride.\n\nForza, dammi i suoi documenti...", "Bene, qui dice che ti è stato conferito il grado di Acting Deputy presso gli Stormwind Marshals. Congratulazioni.\n\nE buona fortuna: tenere al sicuro Elwynn non è una passeggiata... con quasi tutto l'esercito impegnato a fare chissà cosa per chissà quale nobile!\n\nÈ difficile stare dietro alla politica in questi tempi bui...", 0xccb7dcaf, 0xc0ef425f, 0xd8bc24db, 0xf6530924, 0xb56df9b4, "....." },
  [59] = { "Armature di stoffa e di cuoio", "Consegna lo Stormwind Armor Marker a Sara Timberlain.", "Per la tua astuzia e il tuo valore ho qui un buono che vale un pezzo d'armatura. Portalo a Sara Timberlain, all'Eastvale Logging Camp. Dalle il buono e lei ti forgerà l'armatura. E quando l'avrai, {name}, usala per difendere Elwynn.\n\nL'Eastvale Logging Camp si trova oltre il posto di guardia di Guard Thomas, a est.", "La Stormwind Army mi ha incaricata di fornire alla sua gente armature di stoffa e di cuoio.\n\nSe hai un buono per me, sarò felice di prepararti qualcosa.", "Ah, grazie per il buono. Scegli pure l'armatura che preferisci.\n\nBuona fortuna, prode {class}. E che questa armatura ti serva bene.", 0x751bcd47, 0x88cbb6e2, 0xec149fa7, 0xa0219e98, 0xff5c34aa, "....." },
  [60] = { "Candele dei kobold", "Porta 8 Large Candles a William Pestle, a Goldshire.", "Salve, <messere/madama>! Hai un momento?\n\nIo e mio fratello gestiamo una bottega di speziale a Stormwind, e sono qui a raccogliere Large Candles per la loro cera. Puoi aiutarmi?\n\nLe Large Candles si ottengono dai kobold, e si dice che i kobold stiano infestando le miniere di Elwynn... la Fargodeep Mine a sud e la Jasperlode Mine a est. Ti consiglio di cercare le candele in uno di quei posti.", "Hai già raccolto quelle candele?", "Ti sei <dato/data> da fare a cacciare kobold, eh? Grazie per le candele, {name}: ecco la tua ricompensa...", 0x514933bf, 0xd8ce4567, 0x6cce32c4, 0x77e7ca88, 0x98618684, ".....", nil, nil, 0x1993cf97, nil, nil },
  [61] = { "Una spedizione per Stormwind", "Porta la William's Shipment a Morgan Pestle, nello Stormwind Trade District.", "Mio fratello Morgan aspetta a Stormwind la mia spedizione di candele. Non ho tempo di fare il viaggio di persona, ma se vuoi portargli tu la spedizione, ti pagherà bene.\n\nHo impacchettato le candele: troverai Morgan nella nostra bottega, la Pestle's Apothecary, nello Stormwind Trade District.", "Oh, una spedizione da mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Ecco il tuo compenso... e già che sei qui, dai un'occhiata in giro! Di sicuro abbiamo una pozione o un altro gingillo che ti tornerà utile.", 0x6a825135, 0xdeec4138, 0xd71ae934, 0x89b01d8f, 0xdf7db746, "....." },
  [62] = { "La Fargodeep Mine", "Esplora la Fargodeep Mine, poi torna da Marshal Dughan a Goldshire.", "La miniera di Northshire non è l'unica ad avere problemi! Mi riferiscono che anche la Fargodeep Mine, a Elwynn, è diventata un rifugio per i kobold.\n\nEsplora la miniera e conferma queste voci, poi torna da me. La miniera si trova quasi esattamente a sud di Goldshire, tra le fattorie degli Stonefield e dei Maclure.", "Cosa hai da riferire, {name}? Sei <stato/stata> alla Fargodeep Mine?", "Brutte notizie. Cosa ci aspetta ora, i draghi?!? Dovremo aumentare le pattuglie vicino a quella miniera. Grazie per i tuoi sforzi, {name}. E aspetta un momento... forse ho un altro compito per te.", 0x3a373e5c, 0x068c7c5b, 0x196f6d77, 0x620f4981, 0x902000cc, "....." },
  [66] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [67] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [68] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [69] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [70] = { "La leggenda di Stalvan", "Prendi la Stalvan's Undelivered Letter dal baule e consegnala nel Canal District di Stormwind.", "Il nome Stalvan mi dice qualcosa. Ora ricordo.\n\nMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di riparo per la notte. Verso la mezzanotte, l'uomo si precipitò giù per le scale urlando, pallido di paura. Ancora in camicia da notte, sparì sotto l'acquazzone.\n\nNella fretta dimenticò le sue lettere nel baule al piano di sopra, e non tornò mai a riprenderle. Ne è rimasta una di quel tale Stalvan, destinata al Canal District di Stormwind. Prendila pure.", "Cos'hai lì? Fammi dare un'occhiata. . .", "Hai una bella faccia tosta a portare questa roba qui.", 0xeb6571fb, 0xec87b2a9, 0xcf8206e0, 0xad2d2675, 0xf3e822c5, "....." },
  [71] = { "Rapporto a Thomas", "Consegna i Rolf and Malakai's Medallions a Guard Thomas, al ponte orientale di Elwynn.", "Ora che hai entrambi i medaglioni, consegnali a Guard Thomas al ponte, perché sappia che fine hanno fatto le sue guardie assassinate.", "Salve, {name}. Hai scoperto che fine hanno fatto Rolf e Malakai?", "Hai confermato i miei timori, {name}. I murloc sono una minaccia che non possiamo ignorare.", 0xcad5f606, 0xdfec0126, 0xfecbb9ef, 0x8c9b780e, 0xab891fb8, "....." },
  [72] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [74] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [75] = { "La leggenda di Stalvan", "Marshal Haggard vuole che tu cerchi la Faded Journal Page nel baule al piano di sopra.", "Quando mi trasferii qui, nel baule al piano di sopra c'era un fascio di pergamene. Le guardai una volta appena arrivato, ma ci rinunciai quando la nebbia mi annebbiò gli occhi.\n\nFai un favore a un vecchio quasi cieco e guarda nel baule di sopra se c'è qualcosa che possa aiutarti a scoprire di più su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.", "Hai trovato la pagina di cui ti parlavo, {name}?", "L'hai trovata!", 0xeb6571fb, 0x74cb8926, 0x33923181, 0x856913a4, 0x3715d975, "....." },
  [76] = { "La Jasperlode Mine", "Esplora la Jasperlode Mine, poi torna a fare rapporto a Marshal Dughan a Goldshire.", "Grazie a te sappiamo che la Fargodeep Mine è infestata dai kobold. Ora ci serve un esploratore che indaghi sulla Jasperlode Mine, più lontana.\n\nEsplora la Jasperlode e verifica se ci sono kobold. Per raggiungere la miniera, segui la strada verso est fino alla Tower of Azora. Dalla torre vai a nord e troverai la miniera ai piedi delle colline.", "Salute, {name}. Cosa hai da riferire? Hai esplorato la Jasperlode Mine?", "Kobold alla Jasperlode Mine, dici? Maledizione! La situazione peggiora di minuto in minuto!\n\nGrazie per il rapporto, {name}. Ma vorrei che le notizie che mi porti fossero buone.", 0x0323d68b, 0xb489dc45, 0xd63cfe6e, 0x3d82a623, 0xf3bd38e1, "....." },
  [78] = { "La leggenda di Stalvan", "Porta la Faded Journal Page a Tavernkeep Smitts.", "Conosco qualcuno che potrebbe aiutarti. Quando comandavo la Stormwind Guard, andavamo a bere alla Scarlet Raven Tavern, a Darkshire. Il locandiere, Smitts, era un vero esperto delle storie del posto. Mostragli questa pagina e senti cosa ne pensa.", "Ti manda Marshal Haggard? Perché non l'hai detto subito?\n\nAh, il buon vecchio Haggard. Poveretto, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.", "Per la Luce! Puoi scommetterci che riconosco questa calligrafia.", 0xeb6571fb, 0x9665adb8, 0xd11badb8, 0x01f28add, 0x017fe17b, "....." },
  [79] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [80] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [83] = { "Merce di lino rosso", "Porta 6 Red Linen Bandanas a Sara Timberlain, all'Eastvale Logging Camp.", "La banda dei Defias a Northshire porta maschere di tela di sacco, ma i Defias di Elwynn indossano il lino, che posso usare per confezionare ottimi capi.\n\nPortami delle Red Linen Bandanas e le userò per farti qualcosa.\n\nI membri della banda dei Defias hanno accampamenti sparsi in tutta Elwynn.", "Sto finendo il lino, {name}. Ne hai per me?", "Ah, sono belle bandane, anche se un po' ruvide...\n\nEcco qua!", 0xab13ee46, 0x6ab947a0, 0x2f31ce58, 0x13c355f0, 0xb808f80e, "....." },
  [84] = { "Ritorno da Billy", "Porta la Pork Belly Pie a Billy Maclure, ai Maclure Vineyards.", "Ecco qua. E quando dai questa torta a quel Billy, digli che spero gli vada di traverso!", "Uff... sto morendo di fame! Hai quella torta per me, {name}?", "Mmm, che buona! Questa torta è la migliore!\n\nMi sa che mi sta tornando la memoria...", 0x77e92707, 0xb3802d9c, 0x8c11f6b5, 0xa7950cc8, 0x90374641, "....." },
  [85] = { "La collana perduta", "Parla con Billy Maclure.", "Ho perso la mia collana, e credo che l'abbia presa quel monello di Billy Maclure! Di solito zampetta come un ratto intorno ai Maclure Vineyards, a est di qui.\n\nRiportami la collana e scalderai il cuore di una vecchia vedova.", nil, "Hai perso cosa? Be', io nessuna collana ho preso, perché non sono mica un ladro!\n\nForse so chi è stato, ma... <sogghigna>... ho troppa fame per ricordarmelo.", 0x1a691c23, 0x3c0d0519, 0xc37d5922, nil, 0xc488cf29, "...m." },
  [86] = { "Una torta per Billy", "Porta 4 Chunks of Boar Meat ad Auntie Bernice Stonefield, alla Stonefield's Farm.", "Forse, se avessi una torta, potrei dirti chi ha quella collana. E sai, credo che quella vecchia Bernice dell'altra fattoria faccia delle ottime Pork Belly Pie...\n\nMagari, se le dai un po' di carne dei cinghiali che girano intorno alle nostre fattorie e le dici a cosa serve, ti cuocerà una torta.", "Non mi sembra giusto sfamare proprio il ragazzo che mi ha rubato la collana, ma se è questo che serve per riavere ciò che è mio, e sia!\n\nHai quella carne di cinghiale?", "Questa carne di cinghiale selvatico è dura, ma se la fai sobbollire abbastanza viene fuori proprio una torta squisita!", 0xe258953a, 0x3d1f7b01, 0xb9e0bfdc, 0xd53bb684, 0x6b1f64bc, "....." },
  [87] = { nil, "Porta la Bernice's Necklace ad \"Auntie\" Bernice Stonefield, alla Stonefield Farm.", "Stavo giocando vicino alla Fargodeep Mine, e credo di aver perso, ehm... cioè, di aver visto la collana della vecchia. Non chiedermi come ci sia finita... non sono stato io!\n\nBe', comunque, ho visto un kobold grosso, con un dente d'oro, raccogliere la collana e scappare nella miniera. Trova quel kobold e troverai la collana, lo giuro!", "Salve, {name}. Hai trovato la mia collana?", "Oh, l'hai trovata! Grazie, grazie, tesoro!\n\nTieni, prendi questo. Era di mio marito, e diceva sempre che portava fortuna. Se solo non l'avesse dimenticato durante la sua ultima campagna! *snif*", nil, 0xec235807, 0x329228f9, 0x511d94a7, 0x9137e39e, "m...." },
  [88] = { "Princess deve morire!", "Uccidi Princess, prendi il suo collare e portalo a Ma Stonefield, alla Stonefield Farm.", "I Brackwell hanno una maiala che ha vinto dei premi, Princess. La scrofa è enorme, ed è diventata così venendo di nascosto qui a mangiarsi le mie verdure!\n\nQuindi, prima che arrivi ai nostri campi... Princess deve morire! Portami il suo collare come prova e ti darò qualcosa per il disturbo!\n\nDi solito Princess sta nella Brackwell Pumpkin Patch, a est, oltre la fattoria dei Maclure. Prendila prima che le venga fame e torni qui!", "L'hai vista? L'hai presa?", "Meno male! Quella maiala stava diventando così grossa che si sarebbe mangiata tutto il raccolto! Grazie, {name}.\n\nAllora, ti va bene una di queste cose?", 0xd0c3b757, 0x87ee4e48, 0xb6b583eb, 0x6ce3847c, 0x8ee1d213, "....." },
  [94] = { "Un occhio vigile", "Porta il Glyph of Azora alla Lion Statue vicino alla Tower of Ilgalar, a Redridge.", "Il mio rivale, Morganth, è un mago spietato e molto potente che vive nella Tower of Ilgalar, a Redridge. Ho escogitato un modo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.\n\nMa per studiare i suoi pensieri... mi serve altro aiuto.\n\nSe te la senti, porta il mio Glyph of Azora alla Tower of Ilgalar e posalo sulla Lion Statue vicino alla torre.\n\nFatto questo, il potere di Azora mi concederà visioni dei piani futuri di Morganth.", "Questa Lion Statue sta qui da decenni e veglia solitaria sulla famigerata Tower of Ilgalar.\n\nAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...", "Posi il Glyph of Azora sulla pietra. Aderisce da solo... e ne senti uscire la voce senza corpo di Theocritus:\n\nHai la mia gratitudine, giovane {name}. Ora potrai parlarmi attraverso questo glifo, e forse avrò altri compiti per te... dopo aver sondato i pensieri del mio rivale.", 0x4ce3e4cb, 0xae7ae989, 0x32080b45, 0x5d05e43a, 0x338c1c3b, "....." },
  [97] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [98] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [106] = { "Giovani innamorati", "Consegna la Maybell's Love Letter a Tommy Joe Stonefield.", "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono nemiche giurate. Così non posso vederlo, anche se i miei occhi bramano di guardare quel bel viso!\n\nTi prego, prendi questa lettera e dalla a Tommy Joe. Di solito è al fiume a ovest della Stonefield Farm, che si trova proprio a ovest di qui.", "Hai cosa?? Maybell è la luce della mia vita grigia. Presto, fammi vedere la sua lettera!", "Ah! Non sopporto di stare lontano da lei. Devo vederla!!", 0x39bb27e6, 0xaca204cb, 0x455a69fe, 0x8ed56116, 0xaef57c73, "....." },
  [107] = { "Un biglietto per William", "Porta la Gramma Stonefield's Note a William Pestle.", "Scommetto che William Pestle ha una pozione per unire i nostri due giovani innamorati!\n\nTieni, porta questo biglietto a William. Alloggia al Lion's Pride Inn, a Goldshire.", "Hai un biglietto da \"Gramma\" Stonefield, eh? Non vedo Mildred da anni! Chissà cosa ha da dire...", "Il mio cuore soffre per quelle due povere anime, Maybell e Tommy Joe. Ricordo cosa vuol dire essere giovani e innamorati, un tempo.\n\nCi dev'essere qualcosa che posso fare per aiutarli! Fammi pensare...", 0x94227104, 0x6cf2cbc4, 0x613551b1, 0x4d3b404b, 0xd5a99e73, "....." },
  [109] = { "Rapporto a Gryan Stoutmantle", "Parla con Gryan Stoutmantle. Di solito si trova nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", "Mi pare che tu abbia visto parecchie battaglie, {class}. Se non l'hai già fatto, dovresti andare a fare rapporto a Gryan Stoutmantle. È a capo della People's Militia, che protegge i campi di Westfall. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", nil, "Ah, quindi ti manda il mio amico? Che gentile.\n\nBe', la Stormwind Monarchy ha abbandonato la nostra causa. Ora tocca alla People's Militia tenere queste terre libere dalla corruzione. Se la nostra causa ti interessa, posso mettere a frutto le tue doti di combattimento in nome della libertà.", 0xc82e5075, 0x03f579cf, 0x50233a5c, nil, 0xb444ea08, "...m." },
  [111] = { "Parlare con Gramma", "Parla con Gramma Stonefield.", "Ti prego, {name}, parla con la mia Gramma. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.\n\nÈ in casa nostra, a est di qui.", "Non vedo l'ora di sapere come reagiranno i miei amici!\n\nNon se lo aspetteranno mai", "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno un gran futuro, ma... forse possiamo farli stare insieme almeno per un po'.\n\nMmm, cosa possiamo fare...", 0x6b3f9d7c, 0xf51e0819, 0x90033b93, 0x96b93e46, 0x2fa7cabf, "....." },
  [112] = { "Raccolta di alghe", "Porta 4 Crystal Kelp Fronds a William Pestle, a Goldshire.", "Posso preparare per Maybell un Invisibility Liquor, così potrà sgattaiolare via dai Maclure Vineyards e raggiungere Tommy Joe. Ma per fare il liquore mi serve dell'alga cristallina.\n\nDi solito l'alga cresce nell'oceano... ma a volte i murloc la raccolgono. Vedi se i murloc vicino al Crystal Lake ne hanno. Il Crystal Lake è appena a est di Goldshire.", "Hai quell'alga cristallina? Di sicuro Maybell non vede l'ora di vedere il suo innamorato...", "Le hai prese. Ben fatto! Ora un momento solo, mentre preparo la pozione...", 0x2bebb48c, 0x3fc93ac6, 0x9e5c1b2e, 0x73f21124, 0xca7123ec, "....." },
  [114] = { "La fuga", "Porta l'Invisibility Liquor a Maybell Maclure.", "Porta questo Invisibility Liquor alla giovane Maybell. Dovrebbe durare abbastanza perché possa far visita a Tommy Joe.", "Hai consegnato la mia lettera a Tommy Joe? Cosa ha detto??", "Oh... cielo! Mi sento in colpa a ingannare la mia famiglia, ma ciò che provo per Tommy Joe è troppo forte per ignorarlo.\n\nGrazie, {name}. Berrò questo liquore appena potrò e sgattaiolerò via dal mio amore.\n\nE per te... ti prego, prendi questo.", 0x437cedda, 0x7b2f4392, 0x62549b36, 0x692ffc74, 0xe0cf61c2, "....." },
  [119] = { "Ritorno da Verner", "Torna da Verner Osgood a Redridge e consegnagli la Crate of Horseshoes.", "Va bene, gli darò i suoi 50 ferri di cavallo...\n\nEccoli qui, tutti inscatolati e pronti a partire! Di' a Verner che è stato un piacere fare affari con lui, e assicurati che legga il biglietto attaccato a questa cassa!", "Bene, sei <tornato/tornata>! Hai preso i ferri?", "Grazie, questo mi aiuta davvero.\n\nMa cos'è questo? Argus ha mandato un biglietto con la cassa... Cosa?? Argus vuole che sia io a pagarlo? Bah!\n\nBe', {name}, grazie per l'aiuto.", 0x1296097e, 0x49433401, 0xe1ab4783, 0xa467f765, 0x16236c6c, "....." },
  [123] = { nil, "Vai da Marshal Dughan a Goldshire e consegnagli The Collector's Schedule", "Questo foglio è un calendario con un elenco di giorni e orari in cui una persona, descritta solo come \"The Collector\", riceverà una spedizione d'oro dalle miniere della Elwynn Forest.\n\nDal calendario sembra che il Collector si nasconda vicino alla Brackwell Pumpkin Patch, nella parte orientale di Elwynn.\n\nSembra una cosa importante. Dovresti riferirla a Marshal Dughan, a Goldshire.", "Cosa?!? Sono mesi che non abbiamo gente al lavoro nelle miniere di Elwynn!\n\nFammi vedere quel biglietto che hai...", "Mmm... ho sentito parlare di questo \"Collector\", ma non so per chi lavori. Grazie per il calendario. Ci aiuterà a risolvere il mistero.", nil, 0x3b835957, 0x5a3d01e4, 0xb33d4341, 0x318a1e2f, "m...." },
  [147] = { "Caccia all'uomo", "Trova e uccidi \"the Collector\", poi torna da Marshal Dughan con The Collector's Ring.", "Se il \"Collector\" prende l'oro dalle nostre miniere, allora sta derubando il regno! Consegna il Collector alla giustizia e portami l'anello citato nel calendario dei ritiri che mi hai dato. Potrebbe dirci per chi lavora il Collector...\n\nSecondo quel Pickup Schedule, il Collector si nasconde alla Brackwell Pumpkin Patch. Dovresti cercarlo lì.", "Hai trovato il Collector? Hai scoperto per chi lavora?", "L'hai trovato? Ben fatto, {name}. Non \"collezionerà\" più niente dalle Elwynn Mines!\n\nE questo anello che hai trovato è interessante... è un anello di appartenenza alla vecchia Stonemason's Guild di Stormwind. Perché un ladruncolo dovrebbe avere l'anello di una gilda di artigiani, e perché i Defias Thieves raccolgono denaro dalle nostre miniere?\n\nDomande difficili. Spero che un giorno avremo delle risposte.", 0x3fd32b4a, 0xaffbf97d, 0xcaee2d0b, 0x03263e82, 0xe881e64e, "....." },
  [176] = { "RICERCATO: \"Hogger\"", "Uccidi lo gnoll Hogger e porta il suo Huge Gnoll Claw a Marshal Dughan.", "Ricercato: Hogger\n\nUn enorme gnoll, Hogger, si aggira nei boschi della parte sud-occidentale di Elwynn. Ha avuto la meglio su tutti i tentativi di catturarlo.\n\nLa Stormwind Army ha messo una generosa taglia sullo gnoll. Per riscuotere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger a Marshal Dughan, a Goldshire.", "Sì, Hogger è stato una vera spina nel fianco per me e i miei uomini. Hai qualcosa da riferire su quella bestia?", "Ah! Ben fatto! Cominciavo a pensare che nessuno avrebbe abbattuto quel mostro!\n\nEcco a te, {name}. E grazie: quello gnoll mi stava facendo venire un mal di testa grande quanto la Blackrock Spire!", 0x9dcd29e7, 0x318a3a3b, 0xab83e5ae, 0xadee0c74, 0xc7de9815, "....." },
  [178] = { "Un recupero per Theocritus", "Porta il Faded Shadowhide Pendant a Theocritus the Mage.", "<Senti una voce senza corpo...>\n\nNon allarmarti. Sono Theocritus, High Mage della Tower Azora nella Elwynn Forest. Il ciondolo che tieni in mano è un mezzo di comunicazione tra gli Shadowhide Gnolls e il loro padrone, Morganth.\n\nDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi ciondoli. Se senti questo messaggio, il mio incantesimo è riuscito.\n\nPortami questo ciondolo e ti ricompenserò per il servizio.", "Ti ho parlato attraverso un ciondolo, dici? Mmm... dammelo, così posso studiarlo.", "Hai la mia gratitudine, {name}. Ho mandato quel messaggio agli Shadowhide Pendants settimane fa e lo credevo un fallimento. Ma sembra che l'incantesimo abbia raggiunto almeno alcuni ciondoli, con un notevole ritardo.\n\nCol tempo spero di imparare a lanciare un attacco attraverso i ciondoli, per immobilizzare gli Shadowhide Gnolls che li indossano.\n\nMa prima che sia possibile, temo servano molte altre ricerche.", 0xd1b6915b, 0xe9f541db, 0x7788c2a9, 0xdac36d0d, 0xd28bd097, "....." },
  [239] = { "La Westbrook Garrison chiede aiuto!", "Vai alla Westbrook Garrison e parla con Deputy Rainer.", "La guarnigione sul nostro confine occidentale ci avverte che gli gnoll e i ladri sono sempre più attivi. Chiedono che mandiamo altri soldati di Stormwind... ma non ne abbiamo da mandare!\n\nSe puoi aiutarci, ci farebbe comodo. Vai a parlare con Deputy Rainer alla Westbrook Garrison e senti di cosa ha bisogno.\n\nLa guarnigione è più avanti lungo la strada, a ovest. Dopo aver attraversato il ponte sul piccolo ruscello, la trovi sulla destra.", nil, "Ti manda Marshall Dughan, eh? Be', non fai parte dell'esercito, ma se ti manda Dughan per me va più che bene!\n\nLa nostra situazione è, a dir poco, tesa. Spero che tu possa darci una mano.", 0xdc5c2624, 0x2e02a498, 0x8d2938bf, nil, 0x3b449a23, "...m." },
  [249] = { nil, "Sconfiggi Morganth.\n\nPorta il suo Pendant of Shadow a Theocritus, alla Tower of Azora nella Elwynn Forest.", "Dopo lunghe osservazioni, ho scoperto i piani di Morganth.\n\nCerca la Scythe of Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains e il regno di Stormwind sentiranno la sua oscura potenza.\n\nNon sono pronto ad affrontare Morganth, ma temo che vada fermato subito. Perciò devi entrare nella Tower of Ilgalar e affrontarlo.\n\nSconfiggilo e portami il suo Pendant of Shadow. Fallo, e il regno ti sarà molto debitore.", "Presto, {name}, prima che il mio timore che Morganth estenda il suo potere si avveri!", "Hai fatto bene, {name}. Sconfiggendo lo stregone Morganth, hai salvato Stormwind da un grave pericolo.\n\nTi offro questa ricompensa con grande umiltà. E ti augurerei la pace, se questi fossero tempi di pace.\n\nInvece ti auguro fortuna nelle tue prove, e vittoria nei conflitti che verranno.", nil, 0x879964dd, 0x12522098, 0x0143479a, 0x425a6647, "m...." },
  [345] = { "Scorte d'inchiostro", "Parla con Foreman Oslow a Lakeshire e chiedigli del Rethban Iron Ore.", "Volevo finire la mia copia di The Stresses of Iron, ma...\n\nVedi, faccio da me l'inchiostro per i libri che copio. È una mia ricetta: non cola, non sbava e asciuga in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi di copiare, e non ho avuto occasione di farne dell'altro!\n\nPer farne altro mi serve del Rethban Iron Ore dalle Redridge Mountains. Di solito me lo fornisce Foreman Oslow, a Lakeshire.", nil, "Ti serve cosa?? Forse non te ne sei <accorto/accorta>, ma siamo impegnati a rafforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Rethban Iron Ore, dovrai procurartelo da <solo/sola>!", 0x6436fa89, 0x9f82018f, 0xf8e115c5, nil, 0x6eaa5bf6, "...m." },
  [346] = { "Ritorno da Kristoff", "Torna da Brother Kristoff nella Cathedral Square e consegnagli il libro The Stresses of Iron.", "Ora che ho finito di copiare il libro, ecco l'originale di Stresses of Iron. Grazie per la pazienza, e se vedi Milton, digli che mi dispiace per il lungo ritardo.", "Sei <riuscito/riuscita> a trovare il libro?", "È proprio quello! Grazie, {name}. Che la Luce risplenda sul tuo corpo e sul tuo spirito!", 0x7914bcc7, 0xaffc7d2d, 0xa9d0a831, 0xf44efc87, 0xcfcb4f09, "....." },
  [783] = { "Una minaccia interna", "Parla con Marshal McBride.", "Spero che tu abbia stretto bene la cintura, giovane {class}, perché qui a Northshire c'è del lavoro da fare.\n\nE non parlo di lavorare i campi.\n\nLe guardie di Stormwind faticano a mantenere la pace, con tanti di noi in terre lontane e tante minacce sempre più vicine. Per questo arruoliamo chiunque sia disposto a difendere la propria casa. E la propria alleanza.\n\nSe sei qui per rispondere alla chiamata, parla con il mio superiore, Marshal McBride. È dentro l'abbazia, alle mie spalle.", nil, "Ah, bene. Un'altra recluta. Di questi tempi ne arrivano tante.\n\nSpero che basti.\n\nLe terre degli umani sono minacciate dall'esterno, e molte delle nostre forze sono state mandate lontano. Questo, a sua volta, lascia spazio a gruppi corrotti e fuorilegge che prosperano entro i nostri confini.\n\nCombattiamo una battaglia su molti fronti, {name}. Preparati a una lunga campagna.", 0x5dfca6f5, 0x4ec936be, 0x0ab5d4f4, nil, 0x031c7505, "...m." },
  [863] = { "La fuga", nil, nil, nil, nil, 0x437cedda, nil, nil, nil, nil, ".mmmm" },
})
